-- UFC Strike on Aptos: one Aptos collection per edition -> existing ufc_strike edition.
-- ufc_set_id = the collection's IPFS metadata `edition_id` (UFC Strike's edition number) = Flow set_id in ufc_chain_set_editions.
-- Source read 2026-11-15 ~3:40 PM PT: Aptos indexer current_collections_v2, creator 0x80f686c7bba12a0fce839ff160cb69774715497288996b861528727ccd256cdb.
-- Revert: DROP TABLE public.ufc_aptos_collections;
CREATE TABLE public.ufc_aptos_collections (
  aptos_collection_id text PRIMARY KEY CHECK (aptos_collection_id ~ '^0x[0-9a-f]{64}$'),
  ufc_set_id integer NOT NULL UNIQUE,
  edition_id uuid UNIQUE REFERENCES public.editions(id),
  collection_name text,
  max_supply integer,
  current_supply integer,
  supply_read_at timestamptz NOT NULL DEFAULT now(),
  mapped_by text CHECK (mapped_by IN ('flow_set_id','new_on_aptos')),
  created_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.ufc_aptos_collections IS 'UFC Strike on Aptos (Aug 2025 burn-and-mint from Flow, serials preserved). One row per Aptos collection = one ufc_strike edition. ufc_set_id = Aptos metadata edition_id = Flow set_id. A token maps to (edition_id, token_properties."Serial Number"). Creator 0x80f686c7bba12a0fce839ff160cb69774715497288996b861528727ccd256cdb. Flow Origin 1/1 sets 2-36 have no Aptos collection.';
ALTER TABLE public.ufc_aptos_collections ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.ufc_aptos_collections FROM anon, authenticated;

